#include <Cellerator/compiler/diagnostics/implement_target_native_diagnostics_v1.hh>
#include <array>
#include <cassert>
int main(){using namespace cellerator::compiler::diagnostics::v1;constexpr std::array issues{target_native_issue::unsupported_instruction,target_native_issue::capability_range,target_native_issue::clobber,target_native_issue::alignment,target_native_issue::address_space,target_native_issue::collective,target_native_issue::abi,target_native_issue::graph_capture,target_native_issue::fallback_unavailable};for(auto i:issues){assert(!diagnose_target_native({i,validation_mode::checked}).continue_compilation);auto u=diagnose_target_native({i,validation_mode::unsafe,true,false,true});assert(u.continue_compilation&&u.unsafe_continuation);auto f=diagnose_target_native({i,validation_mode::checked,false,true});assert(f.continue_compilation&&!f.unsafe_continuation);}assert(!diagnose_target_native({target_native_issue::abi,validation_mode::unsafe,false,false,true}).continue_compilation);}
